// FIX2 portal edit (item 3) — applied to portal-v1.html (the R5 base the
// build reads); portal.html is REGENERATED by build-official.mjs after.
// Node only. Every replacement asserted exactly-once; a miss fails loudly.
// ITEM 3: #fpRemoveModal was a floating centered card over a dimmed page
// (a pop-up form). Converted to a full-screen in-frame view on the
// #fpStory pattern: opaque fullscreen, content centred in the frame,
// clear round × close in view, Esc already closes (kept), backdrop
// click still closes. No behaviour change to the remove itself.
import {readFileSync, writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
const sha = b => createHash('sha256').update(b).digest('hex');
const F = './portal-v1.html';
const BASE_SHA = 'b7ee02d6177628e5700ae57f819cb7e87f532689245cf639e6d228b080559ee0';
let s = readFileSync(F, 'utf8');
console.log('base', s.length, 'B sha', sha(Buffer.from(s)));
if (sha(Buffer.from(s)) !== BASE_SHA) throw new Error('portal-v1 base sha mismatch — refusing to edit');
const once = (name, from, to) => {
  const n = s.split(from).length - 1;
  if (n !== 1) throw new Error('PATCH ' + name + ': expected 1, found ' + n);
  s = s.replace(from, to);
  console.log('patched', name);
};

// (a) The comment over the rule now states the form.
once('remove-comment',
`/* the remove warning: a real modal in the dial's language, never a bare confirm() */`,
`/* the remove warning: a real modal in the dial's language, never a bare confirm() */
/* FIX2 — full-screen in-frame view (no-pop-ups law, modelled on #fpStory):
   opaque, no floating card over a dimmed page; a clear round × close sits
   in view, Esc closes. The remove itself is untouched. */`);
// (b) The outer layer: dimmed rgba -> opaque, so no page shows through.
once('remove-modal-opaque',
`.fp-remove-modal{position:fixed;inset:0;z-index:90;display:flex;align-items:center;justify-content:center;padding:24px 16px;box-sizing:border-box;background:rgba(0,0,0,.72)}`,
`.fp-remove-modal{position:fixed;inset:0;z-index:90;display:flex;align-items:center;justify-content:center;padding:24px 16px;box-sizing:border-box;background:#02030a}`);
// (c) The card stops being a floating card: it becomes the frame's own
//     centred content — no border, no radius, no shadow, no gradient box.
{
  const start = '.fp-remove-card{position:relative;';
  const a = s.indexOf(start);
  if (a < 0) throw new Error('PATCH remove-card: start not found');
  const b = s.indexOf('\n', a);
  if (b < 0) throw new Error('PATCH remove-card: end not found');
  const cut = s.slice(a, b);
  if (!cut.includes('max-width:480px') || !cut.includes('border:2px solid #ff5e6c')) throw new Error('PATCH remove-card: cut is not the card rule');
  s = s.slice(0, a) + '.fp-remove-card{position:relative;width:100%;max-width:640px;background:transparent;border:0;border-radius:0;box-shadow:none;padding:24px 20px;box-sizing:border-box;color:#fff;text-align:center}' + s.slice(b);
  console.log('patched remove-card (cut', cut.length, 'B)');
}
// (d) The clear close: a round × top-right, in the story close's language,
//     red-rimmed for the warning. Inserted after the Yes-button rule.
once('remove-close-css',
`.fp-remove-yes{border-color:#ff5e6c;box-shadow:inset 0 1.5px 0 rgba(255,255,255,.45),0 0 24px -2px #ff5e6c,0 8px 20px rgba(0,0,0,.55)}`,
`.fp-remove-yes{border-color:#ff5e6c;box-shadow:inset 0 1.5px 0 rgba(255,255,255,.45),0 0 24px -2px #ff5e6c,0 8px 20px rgba(0,0,0,.55)}
.fp-remove-close{position:absolute;top:14px;right:14px;width:44px;height:44px;border-radius:50%;cursor:pointer;color:#fff;background:linear-gradient(180deg,#1b1b24,#050507);border:2px solid #ff5e6c;font-size:25px;line-height:1}
.fp-remove-close:hover{transform:translateY(-2px) scale(1.06)}
.fp-remove-close:active{transform:scale(.97)}`);
// (e) The × button itself, first child of the modal so it sits in view.
once('remove-close-html',
`<div class="fp-remove-modal" id="fpRemoveModal" hidden role="dialog" aria-modal="true" aria-labelledby="fpRemoveTitle">
<div class="fp-remove-card">`,
`<div class="fp-remove-modal" id="fpRemoveModal" hidden role="dialog" aria-modal="true" aria-labelledby="fpRemoveTitle">
<button class="fp-remove-close" id="fpRemoveClose" type="button" aria-label="Close">&times;</button>
<div class="fp-remove-card">`);
// (f) Wire the × to the existing close (Esc + Keep + backdrop already close).
once('remove-close-var',
`  var removeYes=document.getElementById('fpRemoveYes');`,
`  var removeYes=document.getElementById('fpRemoveYes');
  var removeClose=document.getElementById('fpRemoveClose');`);
once('remove-close-wire',
`  if(removeKeep)removeKeep.addEventListener('click',closeRemoveAccount);`,
`  if(removeKeep)removeKeep.addEventListener('click',closeRemoveAccount);
  if(removeClose)removeClose.addEventListener('click',closeRemoveAccount);`);

// Syntax: the script block holding the remove wiring must still parse.
{
  const parts = s.split('<script>');
  let checked = 0;
  for (let i = 1; i < parts.length; i++) {
    const code = parts[i].split('</script>')[0];
    if (!code.includes('fpRemoveModal')) continue;
    try { new Function(code); checked++; } catch (e) { throw new Error('SYNTAX in remove script block: ' + e.message); }
  }
  if (checked !== 1) throw new Error('expected 1 remove script block, found ' + checked);
  console.log('syntax OK: remove script block parses');
}
writeFileSync(F, s, 'utf8');
console.log('wrote', F, s.length, 'B sha', sha(Buffer.from(s)));
console.log('FIX2 PORTAL DONE');
